using System.Collections.Generic;public class NestedIterator{Stack<NestedInteger>st=new();public NestedIterator(IList<NestedInteger>a){for(int i=a.Count-1;i>=0;i--)st.Push(a[i]);}void Prep(){while(st.Count>0&&!st.Peek().IsInteger()){var v=st.Pop().GetList();for(int i=v.Count-1;i>=0;i--)st.Push(v[i]);}}public int Next(){Prep();return st.Pop().GetInteger();}public bool HasNext(){Prep();return st.Count>0;}}
